"""Tabletop Bingo development page and app-specific privacy/support, maintained source."""
from pathlib import Path
from html import escape
from bs4 import BeautifulSoup
ROOT=Path(__file__).resolve().parents[1]
def build(page):
 base='/assets/apps/tabletop-bingo/'
 body=f'''<section class="catalog-hero"><p class="eyebrow">Android bingo game · Coming soon</p><h1>Tabletop Bingo</h1><p class="lead">Big numbers, big buttons, and a bingo game for the whole table.</p><p>Play solo or host a Bluetooth game for nearby friends. Each player gets a card, the host calls numbers at your pace, and you cross off the squares you match. Large text sizes keep the numbers easy to read on phones and tablets.</p><img src="{base}feature.png" width="724" height="361" style="width:100%;height:auto;border-radius:16px" alt="Tabletop Bingo artwork"><p>In development. A public Google Play release has not been announced.</p></section><section><h2>Play your way</h2><p>Play a solo card on your phone, or host a Bluetooth game and let up to five nearby players join. The host approves each player before the game starts.</p><h2>Easy to read</h2><p>Choose from three text sizes. On a tablet in landscape, the card and called numbers sit side by side so the whole table can see the board.</p><h2>Save your solo card</h2><p>Solo games are saved on your device, so you can resume your card after closing the app.</p><h2>Ads and purchases</h2><p>Development builds show Google's demo advertisements between completed rounds, never during play. An optional one-time Remove Ads purchase is handled by Google Play. Final ad settings and product availability will be confirmed before release.</p><h2>See the game</h2><p>Actual Android development-build screenshots; final release details may change.</p><div class="screenshots"><figure><img src="{base}home.png" width="1080" height="2376" loading="lazy" alt="Tabletop Bingo home screen"><figcaption>Start a solo game, host a Bluetooth game, or join one nearby.</figcaption></figure><figure><img src="{base}game.png" width="1080" height="2376" loading="lazy" alt="Tabletop Bingo solo game on a phone"><figcaption>Call the next number and tap to cross off your matches.</figcaption></figure><figure><img src="{base}tablet.png" width="1600" height="1000" loading="lazy" alt="Tabletop Bingo two-column game on a tablet"><figcaption>Tablet landscape view with the card and called numbers side by side.</figcaption></figure></div></section><p><a href="/tabletop-bingo/privacy/">Privacy policy</a> · <a href="/tabletop-bingo/support/">Support</a></p>'''
 page('/tabletop-bingo/','Tabletop Bingo — Android Bingo Game','Play solo or host a nearby Bluetooth bingo game with large, easy-to-read numbers. Coming soon for Android.',body,'https://tripperdeelabs.com'+base+'feature.png')
 policy=(ROOT/'data/tabletop-bingo-privacy.txt').read_text().split('\n\n')
 body='<section><h1>Tabletop Bingo privacy policy</h1>'+''.join('<p>'+escape(p)+'</p>' for p in policy)+'<p>Website analytics are covered separately by the <a href="/privacy/">website privacy policy</a>.</p><p><a href="/tabletop-bingo/">Game overview</a> · <a href="/tabletop-bingo/support/">Support</a></p></section>'
 page('/tabletop-bingo/privacy/','Tabletop Bingo privacy policy','Tabletop Bingo local saves, Bluetooth play, Google AdMob, consent, Google Play purchases and support practices.',body)
 page('/tabletop-bingo/support/','Tabletop Bingo support','How to play solo or Bluetooth bingo, resume a card, reconnect guests, restore purchases and contact TripperDeeLabs.','''<section><h1>Tabletop Bingo support</h1><h2>Solo play</h2><p>Choose Play Solo, then tap a called number to cross it off in green. Tap it again to undo. Repeat plays the last call again. Call Next Number draws the next ball once you have marked the current one. Auto turns the caller on or off.</p><h2>Bluetooth games</h2><p>The host chooses Host Game and keeps the game open. Guests choose Join Game and pick the host from the nearby list. The host approves each guest before cards are dealt. Up to five guests can join one host. If Bluetooth drops, tap Reconnect and ask the host to approve you again.</p><h2>Saved games</h2><p>Your solo card and called numbers are saved on your device, so you can resume after closing the app. Choose Keep Saved Game to continue, or Start New to begin a fresh card.</p><h2>Ads, purchases and privacy</h2><p>Open Settings for Remove Ads, Restore Purchases and privacy choices. Purchases require Google Play and the account used to buy them. Live purchase availability has not been verified for this development build.</p><h2>Contact</h2><p>Email <a href="mailto:tripperdeelabs@gmail.com?subject=Tabletop%20Bingo%20feedback">tripperdeelabs@gmail.com</a> with your app version, phone or tablet model and what happened. Do not include passwords or payment details.</p><p><a href="/tabletop-bingo/">Game overview</a> · <a href="/tabletop-bingo/privacy/">Privacy policy</a></p></section>''')
 home=ROOT/'index.html';soup=BeautifulSoup(home.read_text(),'html.parser');listing=soup.select_one('#in-development .app-directory')
 assert listing is not None
 item=BeautifulSoup(f'<li><a class="directory-preview" href="/tabletop-bingo/"><img src="{base}home.png" width="1080" height="2376" loading="lazy" alt="Tabletop Bingo home screen"></a><div class="directory-copy"><h3><a href="/tabletop-bingo/">Tabletop Bingo</a></h3><p class="availability">Coming soon</p><p>Solo and Bluetooth bingo with large, easy-to-read numbers.</p><p><a href="/tabletop-bingo/">Explore the game</a> · <a href="/tabletop-bingo/privacy/">Privacy</a></p></div></li>','html.parser').li
 listing.insert(0,item);home.write_text(str(soup))
